const PERK_LATER = new Set(['gr_rig']);   // девайсы — батч 7; «Разгрузка» гранаты (+2 гранаты) не нужна — подсумок общий
const perkMax = (p, u) => (PERK_MAX[u.id] && PERK_MAX[u.id][p.gun]) || u.max;
const branchesOf = p => BRANCHES[p.gun] || null;
